const { subtotal } = require('./cart.cjs');
const money = require('./money.cjs');
function invoice(items, percent, basisPoints) {
  const amount = subtotal(items);
  const discounted = money.discount(amount, percent);
  const tax = money.tax(amount, basisPoints);
  return { subtotal: amount, discount: discounted, tax, payable: discounted + tax };
}
module.exports = { invoice };

