const assert = require('node:assert/strict');
const { discount, tax } = require('./src/money.cjs');
const { subtotal } = require('./src/cart.cjs');
const { invoice } = require('./src/invoice.cjs');
assert.equal(subtotal([]), 0);
assert.equal(subtotal([{price:10, quantity:2},{price:3,quantity:4}]),32);
assert.equal(subtotal([{price:0,quantity:7}]),0);
for (const item of [{price:-1,quantity:1},{price:1,quantity:0},{price:1.5,quantity:2},{price:2,quantity:1.5},{price:'2',quantity:1}]) {
  assert.throws(()=>subtotal([item]),RangeError);
  assert.throws(()=>invoice([item],0,0),RangeError);
}
assert.equal(discount(101,25),75);
assert.equal(discount(20,100),0);
assert.equal(discount(20,0),20);
for(const args of [[-1,5],[10,101],[10,-1],[10,1.5],['10',10],[NaN,10],[Infinity,10],[Number.MAX_SAFE_INTEGER+1,0]]) {
  assert.throws(()=>discount(...args),RangeError);
}
assert.equal(tax(75,1000),8);
assert.equal(tax(71,1000),7);
for(const args of [[-1,5],[10,10001],[10,-1],[10,1.5],['10',10]]) assert.throws(()=>tax(...args),RangeError);
assert.deepEqual(invoice([{price:101,quantity:1}],25,1000),{subtotal:101,discount:26,tax:8,payable:83});
assert.deepEqual(invoice([{price:11,quantity:3},{price:17,quantity:4}],25,1000),{subtotal:101,discount:26,tax:8,payable:83});
assert.deepEqual(invoice([],0,0),{subtotal:0,discount:0,tax:0,payable:0});
const items=Object.freeze([Object.freeze({price:11,quantity:3}),Object.freeze({price:17,quantity:4})]);
const before=JSON.stringify(items); invoice(items,25,1000); assert.equal(JSON.stringify(items),before);
console.log('protected shared checkout acceptance passed');
